head.script:
scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        ref: 'data:gdm_ref.key1',
        refSync: wf_sample.getObj("con_refSync").getText(),
    };

    let cList = $c.gcm.createCList(properties);
    // searchbox 엔진은 onkeydown/onkeyup 을 fireEvent 하지 않으므로 eList 에는 onblur 만 등록 (나머지는 native 리스너로 우회)
    let eList = $c.gcm.createEList(["onblur"]);

    await $c.gcm.createBasicSearchBox(cList, eList);

    // native input 요소에 keydown/keyup 직접 등록 (searchbox 미발화 우회)
    if (target1.input && target1.input.render) {
        target1.input.render.addEventListener('keydown', function (e) {
            if (typeof scwin.target1_onkeydown === 'function') scwin.target1_onkeydown(e);
        });
        target1.input.render.addEventListener('keyup', function (e) {
            if (typeof scwin.target1_onkeyup === 'function') scwin.target1_onkeyup(e);
        });
    }

    gdl_ref.setRowPosition(1);
}
